  "about_items": [
    {
      "n": "#253·01",
      "text": "A floor-length dress covered in fine purple sequins, featuring a high mock neck and long sleeves. It flares gently at the hem to skim over your ankles while highlighting your waistline."
    },
    {
      "n": "#403·04",
      "text": "A tailored wool coat in dusty pink with a broad collar that can be worn open or closed. Its structured silhouette and side pockets offer both style and warmth without adding bulk."
    },
    {
      "n": "#288·32",
      "text": "An elegant gold-tone set including a delicate chain necklace with a colorful enamel pendant and matching stud earrings, adding subtle luxury to your ensemble."
    },
    {
      "n": "#141·21",
      "text": "A sophisticated brown suede crossbody bag with a minimalist flap design and polished metal hardware, offering quiet refinement as you move through the evening."
    },
    {
      "n": "#191·10",
      "text": "Brown leather wedge ankle boots with a pointed toe and textured crocodile finish provide height and comfort while maintaining a sleek silhouette under your dress."
    }
  ]
